using EqlTracker.Core;
internal static class BardRotationTests
{
    internal static void Register(Action<string,Action> test)
    {
        void Check(bool value){if(!value)throw new Exception("Bard rotation invariant failed");}
        var at=new DateTime(2026,10,25,12,0,0,DateTimeKind.Local);
        BardSong Song(string name,int? rank=0)=>new(){Identity=new(name,name,rank),Available=true,RequiredLevel=1,Mana=0,CooldownMs=0,NonTargetedArea=true};
        BardPulse Pulse(string id,int second,string song,double? duration=12)=>new(id,at.AddSeconds(second),Song(song),"session",duration);
        test("Bard rotation needs three complete cycles and keeps gems unknown",()=>
        {
            var state=new BardResearchState();foreach(int i in Enumerable.Range(0,2))foreach(string s in new[]{"A","B","C","D","E"})BardRotations.Observe(state,Pulse(i+s,i*7,s));Check(state.Current==null);
            foreach(string s in new[]{"A","B","C","D","E","A"})BardRotations.Observe(state,Pulse("last"+s,14+(s=="A"?7:0),s));
            // Independent regular stream avoids promoting a partial first packet.
            state=new();for(int i=0;i<4;i++)foreach(string s in new[]{"A","B","C","D","E"})BardRotations.Observe(state,Pulse(i+s,i*7,s));
            Check(state.Current?.Songs.Count==5&&state.Current.Songs.All(s=>s.Gem==0)&&state.Common.Single().Cycles>=3);
        });
        test("Bard six-song stream cannot become arbitrary top five",()=>{var s=new BardResearchState();for(int i=0;i<5;i++)foreach(string n in new[]{"A","B","C","D","E","F"})BardRotations.Observe(s,Pulse(i+n,i*6,n));Check(s.Current==null);});
        test("Bard partial missing pulses cannot shrink a previously detected rotation",()=>{var state=new BardResearchState();for(int i=0;i<4;i++)foreach(string s in new[]{"A","B","C"})BardRotations.Observe(state,Pulse(i+s,i*6,s));Check(state.Current?.Songs.Count==3);for(int i=0;i<8;i++)BardRotations.Observe(state,Pulse("partial"+i,30+i*6,"A"));Check(state.Current?.Songs.Count==3);});
        test("Bard duplicate pulse IDs and recipient copies do not multiply recurrence",()=>{var s=new BardResearchState();for(int i=0;i<4;i++){var pulse=Pulse(i.ToString(),i*7,"A");BardRotations.Observe(s,pulse);BardRotations.Observe(s,pulse);BardRotations.Observe(s,pulse with{Id="recipient:"+i});}Check(s.Common.Single().Cycles==4&&s.Common.Single().ObservedSeconds==21);});
        test("Bard unknown durations and long silent gaps do not become uptime",()=>{var s=new BardResearchState();for(int i=0;i<4;i++)BardRotations.Observe(s,Pulse(i.ToString(),i*600,"A",null));Check(s.Current!=null&&s.Common.Single().ObservedSeconds==0);});
        test("Bard boundary prevents combining different sessions into a repeated set",()=>{var s=new BardResearchState();BardRotations.Observe(s,Pulse("1",0,"A"));BardRotations.Observe(s,Pulse("2",7,"A"));BardRotations.Boundary(s,"next");BardRotations.Observe(s,Pulse("3",14,"A"));Check(s.Current==null);});
        test("Bard noneligible and unknown songs are not counted as repeated Aura songs",()=>{foreach(var eligible in new bool?[]{null,false}){var s=new BardResearchState();for(int i=0;i<5;i++)BardRotations.Observe(s,new(i.ToString(),at.AddSeconds(i*6),Song("A").withEligibility(eligible),"s",12));Check(s.Current==null&&s.Known.Count==1);}});
        test("Bard reverse gem selection skips invalid songs and obeys capacity",()=>{var a=Song("Self");a.Gem=14;var b=Song("Mana");b.Gem=13;b.Mana=10;var c=Song("Group");c.Gem=12;var set=new BardRotationSet{Songs=[a,b,c]};Check(BardRotations.Select(set,2).SequenceEqual([a,c]));Check(BardRotations.Select(set,1).Single()==a);b.Mana=null;Check(BardRotations.Select(set,2).Count==0);});
        string Client(int id,string name,int target=41){var f=Enumerable.Repeat("0",171).ToArray();f[0]=id.ToString();f[1]=name;f[43]="1";f[30]=target.ToString();f[32]="41";f[167]=f[168]=f[169]="-1";f[170]="1|4|30|0|100|30";return string.Join('^',f);}
        var index=new ConnectedSpellIndex([]).WithClientLines([Client(1,"Reviewed Song"),Client(2,"Amplification",6)],"fixture");
        test("Bard backfill must wait for a validated song catalog before consuming log metadata",()=>{Check(!BardRotations.MetadataReady(new ConnectedSpellIndex([])));Check(BardRotations.MetadataReady(index));});
        test("Bard memorization proves knowledge and rank without proving a rotation",()=>{var s=new BardResearchState();Check(BardRotations.Memorized(s,"You have finished memorizing Reviewed Song VI.",at,index));Check(s.Known.Single().Value.Song.Identity.UpgradeRank==6&&s.Current==null);Check(!BardRotations.Memorized(s,"You begin casting Reviewed Song VI.",at,index));});
        test("Bard bare memorization preserves unknown rank while explicit zero remains recorded",()=>{var s=new BardResearchState();BardRotations.Memorized(s,"You have finished memorizing Reviewed Song.",at,index);Check(s.Known.Single().Value.Song.Identity.UpgradeRank==null);Check(BardRotations.ObservedIdentity(index,"Reviewed Song +0").Rank==0);});
        test("Bard current 174-field client layout preserves class skill and effect offsets",()=>{var old=Client(3,"Current Song").Split('^');var row=Enumerable.Repeat("0",174).ToArray();Array.Copy(old,row,166);row[12]="20.5";row[165]="0.0";row[166]="-99";row[167]="1";row[168]="177700";row[169]=row[170]=row[171]="-1";row[172]="1";row[173]=old[170];var ready=new ConnectedSpellIndex([]).WithClientLines([string.Join('^',row)],"current");Check(ready.BardSongs.Count==1&&ready.BardSongs[0].Skill=="Singing"&&ready.BardSongs[0].Parameters!.Single().Base==30&&ready.BardSongs[0].Instant==false);row[167]="bad";Check(!BardRotations.MetadataReady(new ConnectedSpellIndex([]).WithClientLines([string.Join('^',row)],"rejected")));});
        test("Bard saved inuse is not an active set; Self remains eligible",()=>{var sets=BardRotations.SavedLoadouts("[SpellLoadouts]\nSpellLoadout1.inuse=1\nSpellLoadout1.name=Saved fixture\nSpellLoadout1.slot14=2\nSpellLoadout1.slot13=1\nSpellLoadout2.inuse=0\nSpellLoadout2.slot14=1",index,"fixture hash");Check(sets.Count==1&&sets[0].Songs.Count==2&&sets[0].Origin.Contains("unconfirmed")&&BardRotations.Select(sets[0],1).Single().Identity.Name=="Amplification");});
        test("Bard unresolved saved spell IDs block unsafe reverse selection",()=>{var sets=BardRotations.SavedLoadouts("[SpellLoadouts]\nSpellLoadout1.inuse=1\nSpellLoadout1.slot14=999\nSpellLoadout1.slot13=1",index,"fixture");Check(BardRotations.Select(sets.Single(),1).Count==0);});
        EffectInput E(BardSong s,string family,double? amount)=>new(){Identity=s.Identity,Family=family,Amount=amount,Quality=amount.HasValue?EvidenceQuality.UserConfirmed:EvidenceQuality.Unknown,Source="Reviewed fixture",Channel=EffectChannel.Attribute};
        BardComparisonInput Fixture(BardSong current,BardSong replacement,double own=30,double other=40)
        {
            var outside=Song("Covered song",6);var rule=new EffectRule{Id="covered",Family="STR",SpellIds=[current.Identity.SpellId,outside.Identity.SpellId],Kind=EffectRuleKind.Strongest,Quality=EvidenceQuality.UserConfirmed,Source="Reviewed stacking group",Version="1"};
            var coverage=new CoverageObservation{Song=outside.Identity,Caster="OtherBard",Recipient="Hero",At=at.AddSeconds(-1),Until=at.AddSeconds(60),SuccessfulApplication=true,Attribution=EvidenceQuality.Observed,Effects=[E(outside,"STR",other)]};
            var facts=new Dictionary<string,BardSongFact>{{BardSongComparison.FactKey(current),new(current,"Singing",[new(E(current,"STR",own),true)],true,"Fixture")},{BardSongComparison.FactKey(replacement),new(replacement,"Singing",[new(E(replacement,"ManaRegen",5),true)],true,"Fixture")}};
            return new(new(){Id="fixture",Name="Fixture",Songs=[current]},new(){ConfirmedAuraRank=1},[replacement],facts,[coverage],new HashSet<string>{"Hero","OtherBard"},new(){Character="Hero",Recipient="Hero",Classes=["BRD"],CasterLevel=50},[rule],null,true,at,[]);
        }
        test("Bard higher rank blocks stronger low-rank magnitude inside a supported overlap group",()=>{var own=Song("My song",2);var input=Fixture(own,Song("Mana"),100,20);var row=BardSongComparison.Evaluate(input).Rows.Single();Check(row.Options.Count==1);var higher=input with{Set=new(){Songs=[Song("My song",9)]}};Check(BardSongComparison.Ranked([E(Song("a",9),"STR",10),E(Song("b",2),"STR",100)],[new(){Family="STR",SpellIds=["a","b"],Kind=EffectRuleKind.Strongest,Quality=EvidenceQuality.UserConfirmed,Source="fixture",Version="1"}],input.Context).Single().Amount==10);});
        test("Bard lower ranks in unrelated stacking groups are not removed",()=>{var c=new EvaluationContext();Check(BardSongComparison.Ranked([E(Song("a",9),"STR",10),E(Song("b",2),"STR",100)],[],c).Count==2);});
        test("Bard recipient stale failures and unknown rank cannot justify a replacement",()=>{foreach(string mode in new[]{"recipient","stale","failed","rank"}){var i=Fixture(Song("My song",2),Song("Mana"));var cov=i.Coverage[0];if(mode=="recipient")cov.Recipient="Pet";if(mode=="stale")cov.Until=at;if(mode=="failed")cov.SuccessfulApplication=false;if(mode=="rank")cov.Song=cov.Song with{UpgradeRank=null};Check(BardSongComparison.Evaluate(i).Rows.Single().Options.Count==0);}});
        test("Bard useful secondary components and Keep prevent swaps",()=>{var s=Song("My song",2);var i=Fixture(s,Song("Mana"));var fact=i.Facts[BardSongComparison.FactKey(s)];var facts=i.Facts.ToDictionary(k=>k.Key,v=>v.Value);facts[BardSongComparison.FactKey(s)]=fact with{Components=fact.Components.Concat([new(E(s,"ResistFire",20),false)]).ToArray()};Check(BardSongComparison.Evaluate(i with{Facts=facts}).Rows.Single().Options.Count==0);s.Keep=true;Check(BardSongComparison.Evaluate(i).Rows.Single().Options.Count==0);});
        test("Bard unknown modifiers are not zero and haste does not receive instrument scaling",()=>{var s=Song("Singing song");var i=Fixture(s,Song("Mana"));var facts=i.Facts.ToDictionary(k=>k.Key,v=>v.Value);facts[BardSongComparison.FactKey(s)]=new(s,"Singing",[new(E(s,"STR",30),true),new(E(s,"HastePercent",30),false)],false,"Fixture");var unreviewed=BardSongComparison.Effects([s],i with{Facts=facts});Check(unreviewed[0].Amount==null&&unreviewed[1].Amount==30);var modifier=new BardModifierCapture{Source="Review",FinalMultipliers=new(){["Singing"]=1.6}};var reviewed=BardSongComparison.Effects([s],i with{Facts=facts,Modifier=modifier});Check(reviewed[0].Amount==48&&reviewed[1].Amount==30);});
        test("Bard Amplification needs rank-matched combined potency and includes its slot cost",()=>{var s=Song("Singing song",2);var amp=Song("Amplification",4);var i=Fixture(s,amp);var mod=new BardModifierCapture{Source="Paired inspect",FinalMultipliers=new(){["Singing"]=1.5},WithAmplification=1.8,AmplificationRank=4};var effects=BardSongComparison.Effects([s,amp],i with{Modifier=mod});Check(Math.Abs(effects.Single().Amount!.Value-36)<.00001);Check(BardSongComparison.Effects([s,amp],i with{Modifier=mod.withRank(3)}).Any(e=>e.Amount==null));Check(BardSongComparison.Evaluate(i with{Modifier=mod}).Rows.Single().Options.Count==0);});
        test("Bard persistence checkpoint is atomic additive and independent",()=>{string path=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".db");using(var db=new TrackerStore(path)){db.Set("checkpoint",new FileCheckpoint{Offset=99});var s=new BardResearchState();s.Preferences.SelectedSet="pinned";s.Preferences.EffectiveStrength=false;db.SaveBardResearch(s,new(){Offset=44});Check(db.Get<BardResearchState>(BardRotations.Version)!.Preferences.SelectedSet=="pinned"&&!db.Get<BardResearchState>(BardRotations.Version)!.Preferences.EffectiveStrength&&db.Get<FileCheckpoint>(BardRotations.Version+":checkpoint")!.Offset==44&&db.Get<FileCheckpoint>("checkpoint")!.Offset==99);}Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();File.Delete(path);});
    }
    private static BardSong withEligibility(this BardSong song,bool? eligible){song.NonTargetedArea=eligible;return song;}
    private static BardModifierCapture withRank(this BardModifierCapture capture,int rank){var copy=EquipmentPositions.Copy(capture);copy.AmplificationRank=rank;return copy;}
}
